"use client";

import { Kicker } from "@/components/ui-fitcheck/kicker";
import { LocationPicker } from "./location-picker";
import type { City } from "@/lib/weather/geocode";

/**
 * Changing your location from Settings.
 *
 * A sheet, not an inline expansion. The first attempt expanded the picker
 * inside the Location row and it read as a card inside a card — two borders,
 * two backgrounds, an inner box floating in its own margin. That presentation
 * was drawn for the Stylist, where it FLOATS OVER the page rather than nesting
 * inside another surface.
 *
 * A sheet is also the better fit for what this is: a searchable list of unknown
 * length. Inline, the row grows as results arrive and reflows the page under
 * the user's thumb, and the search field can end up beneath the keyboard. The
 * project already reaches for a sheet in exactly this situation (`RefineSheet`,
 * `UpgradeSheet`).
 *
 * ⚠️ `fixed` and `z-[70]`, never `absolute`. `MobileNav` is `z-50` and renders
 * after the page content, so at equal z-index it paints straight over a sheet.
 * `RefineSheet` shipped with this bug AND was an `absolute` child of a
 * `overflow-hidden` `<main>`, which clipped it outright.
 */
export function LocationSheet({
  open,
  currentLabel,
  cities,
  onSearch,
  onPick,
  onUseMyLocation,
  locating = false,
  geoError = null,
  onClose,
}: {
  open: boolean;
  currentLabel?: string;
  cities: City[];
  onSearch: (q: string) => void;
  onPick: (c: City) => void;
  onUseMyLocation?: () => void;
  locating?: boolean;
  geoError?: string | null;
  onClose: () => void;
}) {
  if (!open) return null;

  return (
    <>
      <button
        type="button"
        aria-label="Close"
        onClick={onClose}
        className="fixed inset-0 z-[60] bg-[rgba(6,6,8,0.5)] backdrop-blur-[1.5px]"
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-label="Location"
        // maxWidth inline: the shell caps at 440, and a sheet wider than it
        // would hang off the app on a desktop viewport.
        style={{ maxWidth: 440 }}
        className="fixed inset-x-0 bottom-0 z-[70] mx-auto rounded-t-[22px] border-t border-[rgba(237,230,216,0.12)] bg-surface-2 px-[22px] pb-[calc(env(safe-area-inset-bottom)+20px)] pt-3.5"
      >
        <div className="mx-auto mb-4 h-1 w-[34px] rounded-full bg-faint" />

        <Kicker className="block">Location</Kicker>
        <h2 className="mt-2 font-serif text-[24px]/[1.15] text-foreground">
          Where are you dressing for?
        </h2>
        <p className="mt-2 text-sm/[1.5] text-muted-foreground text-pretty">
          Your looks are built around this forecast.
        </p>

        {(locating || geoError) && (
          <p role="status" className="mt-3 text-[12.5px] text-brand-high">
            {locating ? "Locating…" : geoError}
          </p>
        )}

        {/* The list gets its own height and scrolls, rather than growing the
            surface it sits in. `bare` because this card is the surface. */}
        <div
          data-testid="location-results"
          className="mt-4 max-h-[46vh] overflow-y-auto rounded-[14px] bg-surface-1 shadow-[inset_0_0_0_1px_var(--hairline-2)]"
        >
          <LocationPicker
            variant="bare"
            cities={cities}
            currentLabel={currentLabel}
            onSearch={onSearch}
            onPick={onPick}
            onUseMyLocation={onUseMyLocation}
          />
        </div>

        <button
          type="button"
          onClick={onClose}
          className="mt-3 min-h-[44px] w-full text-[14px] text-muted-foreground"
        >
          Cancel
        </button>
      </div>
    </>
  );
}

"use client";

import { cn } from "@/lib/utils";
import type { City } from "@/lib/weather/geocode";

const HAIR2 = "border-[rgba(237,230,216,0.12)]";

/**
 * The city menu, shared by the Stylist's weather pill and the Settings location
 * row. Presentational — all browser-API state lives in `useLocationPicker`.
 *
 * Lifted verbatim from `weather-strip.tsx` so the two screens cannot drift into
 * offering different ways to change the same setting.
 *
 * The `locating` / `geoError` status line is deliberately NOT here: the Stylist
 * shows it even with the menu closed (you tap "use my location", the menu
 * dismisses, and the feedback has to survive that), while Settings shows it
 * beside its row. Placement is a per-screen concern, so each renders its own.
 */
export function LocationPicker({
  cities,
  currentLabel,
  onSearch,
  onPick,
  onUseMyLocation,
  variant = "overlay",
  className,
}: {
  cities: City[];
  currentLabel?: string;
  onSearch: (q: string) => void;
  onPick: (c: City) => void;
  /** Omitted when the browser has no geolocation at all — then search is the only path. */
  onUseMyLocation?: () => void;
  /**
   * `overlay` floats over the page (the Stylist's weather pill) and carries its
   * own card. `bare` has no surface of its own and uses hairline-divided rows,
   * for when it already sits inside one — nesting the overlay inside another
   * card produced two borders and two backgrounds, which is what made it look
   * wrong in Settings.
   */
  variant?: "overlay" | "bare";
  className?: string;
}) {
  const bare = variant === "bare";
  const row = bare
    ? "flex min-h-11 w-full items-center px-4 py-[13px] text-left text-[14px] text-foreground"
    : "flex min-h-11 w-full items-center rounded-[8px] px-3 text-left text-[13px] text-foreground hover:bg-foreground/5";
  return (
    <div className={className}>
      <ul
        role="listbox"
        aria-label="Choose a city"
        className={cn(
          "w-full",
          bare ? "overflow-hidden" : cn("rounded-[12px] border bg-surface-3 p-1.5", HAIR2),
        )}
      >
        {onUseMyLocation && (
          <li>
            <button
              type="button"
              onClick={onUseMyLocation}
              className={cn(row, "gap-2")}
              style={bare ? { borderBottom: "1px solid var(--hairline-2)" } : undefined}
            >
              <svg
                width="11"
                height="11"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.2"
                aria-hidden="true"
              >
                <circle cx="12" cy="12" r="3.2" />
                <path d="M12 2v3.2M12 18.8V22M22 12h-3.2M5.2 12H2" strokeLinecap="round" />
              </svg>
              Use my location
            </button>
          </li>
        )}
        <li className={bare ? "px-4 py-3" : "p-1"}>
          <input
            aria-label="Search a city"
            placeholder="Search a city…"
            onChange={(e) => onSearch(e.target.value)}
            className={cn(
              "w-full rounded-[10px] text-foreground outline-none placeholder:text-muted-dim",
              bare
                ? "bg-surface-3 px-3.5 py-3 text-[15px]"
                : "bg-surface-1 px-3 py-2 text-sm",
            )}
          />
        </li>
        {cities.map((c) => (
          <li key={`${c.name}-${c.lat}`}>
            <button
              type="button"
              role="option"
              aria-selected={c.name === currentLabel}
              onClick={() => onPick(c)}
              className={cn(row, "justify-between")}
              style={bare ? { borderTop: "1px solid var(--hairline-2)" } : undefined}
            >
              {c.name}
              <span className={bare ? "text-[12.5px] text-muted-dim" : "text-[10px] text-muted-dim"}>
                {c.country}
              </span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

